source_queries.sizing.sql:
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout='12s'; SET LOCAL lock_timeout='300ms';
WITH d AS MATERIALIZED (SELECT * FROM trading_decisions WHERE account_id IN(43002148,46130058,47790949,49236051) AND at>='2026-11-10T11:45Z' AND at<'2026-11-10T22:19Z')
SELECT jsonb_build_object('captured_at',now(),'read_only',current_setting('transaction_read_only'),
'day_decision_counts',(SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT account_id,symbol,kind,reason,count(*) records,min(at) first_at,max(at) last_at FROM d GROUP BY account_id,symbol,kind,reason) x),
'sizing_decisions',(SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT * FROM d WHERE reason ILIKE '%min_volume%' OR reason ILIKE '%margin%' OR kind ILIKE '%margin%' OR (kind='s3_pullback_state' AND reason='armed_pullback')) x),
'symbols',(SELECT jsonb_agg(to_jsonb(s)-'raw') FROM symbols s WHERE account_id IN(43002148,46130058,47790949,49236051) AND name IN('SpotCrude','SpotBrent','US500','NAS100','XAUUSD','XAGUSD','BTCUSD','ETHUSD')),
'latest_trader_reads',(SELECT jsonb_agg(to_jsonb(x)-'raw') FROM (SELECT DISTINCT ON(account_id) * FROM trader_reads WHERE account_id IN(43002148,46130058,47790949,49236051) ORDER BY account_id,id DESC) x));
ROLLBACK;

source_queries.session-audit.sql:
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;SET LOCAL statement_timeout='12s';SET LOCAL lock_timeout='300ms';
WITH d AS MATERIALIZED(SELECT * FROM trading_decisions WHERE account_id IN(43002148,46130058,47790949,49236051) AND at>='2026-11-10T11:45Z' AND at<'2026-11-10T22:19Z')
SELECT jsonb_build_object('captured_at',now(),'read_only',current_setting('transaction_read_only'),
'session_events',(SELECT jsonb_agg(to_jsonb(v)) FROM (SELECT account_id,symbol,at,kind,reason,detail FROM d WHERE kind='s3_session' ORDER BY at) v),
's3_hourly',(SELECT jsonb_agg(to_jsonb(v)) FROM (SELECT account_id,date_trunc('hour',at AT TIME ZONE 'Asia/Singapore') as hour_sgt,kind,split_part(reason,' [',1) reason,count(*) records FROM d WHERE kind IN('s3_pullback_assessment','s3_pullback_state','s3_skip','s3_sent','s3_refused') GROUP BY 1,2,3,4 ORDER BY 2,1,3,4) v),
'day_closing_cash',(SELECT jsonb_agg(to_jsonb(v)) FROM (SELECT account_id,date(executed_at AT TIME ZONE 'Asia/Singapore') day_sgt,count(*) closing_deals,sum((close_gross_profit+coalesce(close_swap,0)-abs(coalesce(close_commission,0))-abs(coalesce(close_pnl_conversion_fee,0)))/power(10::numeric,close_money_digits)) net_cash_usd FROM deals WHERE account_id IN(43002148,46130058,47790949,49236051) AND is_closing AND executed_at>='2026-11-09T16:00Z' AND executed_at<'2026-11-10T22:19Z' GROUP BY 1,2 ORDER BY 2,1) v));ROLLBACK;
